public int CanCompleteCircuitBrute(int[] gas, int[] cost)
{
    int n = gas.Length;

    for (int start = 0; start < n; start++)
    {
        int tank = 0;
        bool ok = true;

        for (int step = 0; step < n; step++)
        {
            int i = (start + step) % n;
            tank += gas[i] - cost[i];

            if (tank < 0)
            {
                ok = false;
                break;
            }
        }

        if (ok) return start;
    }

    return -1;
}

public int CanCompleteCircuit(int[] gas, int[] cost)
{
    int totalSurplus = 0;
    int currentSurplus = 0;
    int candidateStart = 0;

    for (int i = 0; i < gas.Length; i++)
    {
        int net = gas[i] - cost[i];

        totalSurplus += net;
        currentSurplus += net;

        // This run failed - no point starting anywhere in it
        if (currentSurplus < 0)
        {
            candidateStart = i + 1;
            currentSurplus = 0;
        }
    }

    // A full circuit is possible only if the overall balance is non-negative
    return totalSurplus >= 0 ? candidateStart : -1;
}

public int CanCompleteCircuit(int[] gas, int[] cost)
{
    int totalSurplus = 0, currentSurplus = 0, candidateStart = 0;

    for (int i = 0; i < gas.Length; i++)
    {
        int net = gas[i] - cost[i];
        totalSurplus += net;
        currentSurplus += net;

        if (currentSurplus < 0)
        {
            candidateStart = i + 1;
            currentSurplus = 0;
        }
    }

    return totalSurplus >= 0 ? candidateStart : -1;
}
